"""Vendored Grimme DFT-D3 reference parameters (BJ-damping variant).

Generated by scripts/gen_d3_params.py from dftbplus/dftd3-lib (a verbatim
repackaging of S. Grimme's dftd3). Physical reference data from Grimme,
Antony, Ehrlich, Krieg, J. Chem. Phys. 132, 154104 (2010); BJ damping
from Grimme, Ehrlich, Goerigk, J. Comput. Chem. 32, 1456 (2011).

Units are atomic (Bohr, Hartree); the caller converts at the boundary.

R2R4[Z-1] = sqrt(0.5 * <r^4>/<r^2>_Z * sqrt(Z)) (the C8 scaling factor).
RCOV[Z-1] = covalent radius scaled by k2=4/3 and in Bohr. Both cover
Z=1..94. C6AB is CN-resolved reference C6 for the element subset
H, He, Li, Be, B, C, N, O, F, Ne, Na, Mg, Al, Si, P, S, Cl, Ar, K, Ca, Sc, Ti, V, Cr,
Mn, Fe, Co, Ni, Cu, Zn, Ga, Ge, As, Se, Br, Kr;
each (Z_a, Z_b) maps to reference points (i, j, C6ref, CN_a_i, CN_b_j).
Extend SUBSET in the generator to add more elements, then re-run.
"""

